(32178, 'LiveBit', 'dbo', 'TempCustMonitorConfigL2', 'UnionSQLAllExecute', 73, NULL, 'varchar', '428', '428', NULL, NULL, 'CAST([UnionSQLAllExecute] AS NVARCHAR(MAX))', 'CAST(UnionSQLAllExecute AS VARCHAR(MAX))', 1, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, NULL, NULL, 'All ONE', 'SELECT Distinct Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue INTO #TempConfigValueL2 From DMS_SAP_Medicine UNION SELECT Distinct Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) From DMS_SQL_Medicine UNION SELECT Distinct Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) From DMS_FTP_Medicine', NULL, NULL, NULL, NULL, '2025-03-17 18:11:14.337000', '2025-03-17 18:13:26.067000', '2025-03-17 18:13:26.067000', NULL),
(32179, 'LiveBit', 'dbo', 'TempCustMonitorConfigL2', 'LoadSQLFactL1Monitor', 74, NULL, 'varchar', '1210', '1210', NULL, NULL, 'CAST([LoadSQLFactL1Monitor] AS NVARCHAR(MAX))', 'CAST(LoadSQLFactL1Monitor AS VARCHAR(MAX))', 1, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, NULL, NULL, 'All ONE', 'INSERT INTO #DMS_FactL2Monitor
( [BusinessPartner],[ConfigValue], [IsSAP], [IsSQL],[IsFTP])
SELECT Distinct 
MAIN.[BusinessPartner]
,MAIN.ConfigValue
, CASE WHEN  SAP.ConfigValue IS NULL THEN 0 ELSE 1 END AS IsSAP
, CASE WHEN  SQL.ConfigValue  IS NULL THEN 0 ELSE 1 END AS IsSQL
, CASE WHEN  FTP.ConfigValue  IS NULL THEN 0 ELSE 1 END AS IsFTP
FROM #TempConfigValueL2 main
LEFT JOIN (SELECT Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue FROM DMS_SAP_Medicine ) SAP  
ON MAIN.ConfigValue = SAP.ConfigValue AND main.[BusinessPartner]=SAP.[BusinessPartner] 
LEFT JOIN (SELECT Cast(MedicineID As Varchar(200))  AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue From DMS_SQL_Medicine  ) SQL  
ON MAIN.ConfigValue = SQL.ConfigValue AND main.[BusinessPartner]=SQL.[BusinessPartner] 
LEFT JOIN (SELECT Cast(MedicineID As Varchar(200))  AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue From DMS_FTP_Medicine ) FTP  
ON MAIN.ConfigValue = FTP.ConfigValue AND main.[BusinessPartner]=FTP.[BusinessPartner] 
Where  MAIN.ConfigValue is not null and len(MAIN.ConfigValue)>0 and MAIN.[BusinessPartner] is not null', NULL, NULL, NULL, NULL, '2025-03-17 18:11:14.337000', '2025-03-17 18:13:26.067000', '2025-03-17 18:13:26.067000', NULL),
